import React, { useEffect, useState } from 'react';
import Table from '../components/table/Table';
import { database } from '../components/Firebase/firebaseConfig';
import { ref, onValue, set, remove } from 'firebase/database';

const categoryTableHead = [
    'STT',
    'ID',
    'Tên danh mục',
    'Hình ảnh',
    'Hành động'
];

const Categories = () => {
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [showAddForm, setShowAddForm] = useState(false);
    const [newCategory, setNewCategory] = useState({
        id: '',
        title: '',
        picUrl: ''
    });

    useEffect(() => {
        const categoriesRef = ref(database, 'Category');
        
        const unsubscribe = onValue(categoriesRef, (snapshot) => {
            try {
                const data = snapshot.val();
                if (data) {
                    const categoryList = Object.entries(data)
                        .map(([key, value]) => ({
                            id: key,
                            ...value
                        }))
                        .sort((a, b) => parseInt(a.id) - parseInt(b.id));
                    
                    setCategories(categoryList);
                }
                setLoading(false);
            } catch (err) {
                console.error("Error reading categories:", err);
                setError(err.message);
                setLoading(false);
            }
        });

        return () => unsubscribe();
    }, []);

    const handleAddCategory = () => {
        const maxId = categories.reduce((max, category) => {
            const categoryId = parseInt(category.id);
            return categoryId > max ? categoryId : max;
        }, 0);
        
        setNewCategory({
            id: (maxId + 1),
            title: '',
            picUrl: ''
        });
        setShowAddForm(true);
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setNewCategory({
            ...newCategory,
            [name]: value
        });
    };

    const submitCategory = (e) => {
        e.preventDefault();
        
        if (!newCategory.title || !newCategory.picUrl) {
            alert('Vui lòng điền đầy đủ thông tin bắt buộc (Tên danh mục và URL hình ảnh)');
            return;
        }

        set(ref(database, `Category/${newCategory.id}`), newCategory)
            .then(() => {
                alert('Thêm danh mục thành công!');
                setNewCategory({
                    id: '',
                    title: '',
                    picUrl: ''
                });
                setShowAddForm(false);
            })
            .catch(error => {
                console.error("Error adding category: ", error);
                alert('Có lỗi xảy ra khi thêm danh mục');
            });
    };

    // 🗑️ Hàm xóa danh mục
    const handleDeleteCategory = (categoryId) => {
        if (window.confirm('Bạn có chắc chắn muốn xóa danh mục này không?')) {
            const categoryRef = ref(database, `Category/${categoryId}`);
            
            remove(categoryRef)
                .then(() => {
                    alert('Xóa danh mục thành công!');
                })
                .catch(error => {
                    console.error("Error deleting category: ", error);
                    alert('Có lỗi xảy ra khi xóa danh mục');
                });
        }
    };

    // 🧾 Hàm render header
    const renderHead = (item, index) => <th key={index}>{item}</th>;

    // 🧾 Hàm render body (có thêm nút Xóa)
    const renderBody = (item, index) => (
        <tr key={index}>
            <td>{index + 1}</td>
            <td>{item.id}</td>
            <td>{item.title}</td>
            <td>
                <img 
                    src={item.picUrl} 
                    alt="category" 
                    style={{ width: '50px', height: '50px', objectFit: 'cover' }} 
                />
            </td>
            <td>
                <button 
                    className="btn-delete"
                    onClick={() => handleDeleteCategory(item.id)}
                >
                    Xóa
                </button>
            </td>
        </tr>
    );

    if (loading) return <div>Loading...</div>;
    if (error) return <div>Error: {error}</div>;

    return (
        <div>
            <div className="page-header">
                <h2>Danh mục sản phẩm</h2>
                <button 
                    className="btn btn-add" 
                    onClick={handleAddCategory}
                >
                    + Thêm danh mục
                </button>
            </div>

            {showAddForm && (
                <div className="add-form">
                    <h3>Thêm danh mục mới</h3>
                    <form onSubmit={submitCategory}>
                        <div className="form-group">
                            <label>ID danh mục:</label>
                            <input
                                type="text"
                                name="id"
                                value={newCategory.id}
                                onChange={handleInputChange}
                                disabled
                            />
                        </div>

                        <div className="form-group">
                            <label>Tên danh mục: <span className="required">*</span></label>
                            <input
                                type="text"
                                name="title"
                                value={newCategory.title}
                                onChange={handleInputChange}
                                required
                            />
                        </div>

                        <div className="form-group">
                            <label>URL hình ảnh: <span className="required">*</span></label>
                            <input
                                type="text"
                                name="picUrl"
                                value={newCategory.picUrl}
                                onChange={handleInputChange}
                                required
                                placeholder="https://example.com/image.jpg"
                            />
                            {newCategory.picUrl && (
                                <div className="image-preview">
                                    <img 
                                        src={newCategory.picUrl} 
                                        alt="Preview" 
                                        style={{ width: '100px', height: '100px', marginTop: '10px' }} 
                                    />
                                </div>
                            )}
                        </div>

                        <div className="form-actions">
                            <button type="submit" className="btn-submit">Lưu</button>
                            <button 
                                type="button" 
                                onClick={() => setShowAddForm(false)} 
                                className="btn-cancel"
                            >
                                Hủy
                            </button>
                        </div>
                    </form>
                </div>
            )}

            <div className="row">
                <div className="col-12">
                    <div className="card">
                        <div className="card__body">
                            <Table
                                limit='10'
                                headData={categoryTableHead}
                                renderHead={renderHead}
                                bodyData={categories}
                                renderBody={renderBody}
                            />
                        </div>
                    </div>
                </div>
            </div>

            <style jsx>{`
                .btn-delete {
                    background: #f44336;
                    color: white;
                    padding: 5px 10px;
                    border: none;
                    border-radius: 4px;
                    cursor: pointer;
                }
                .btn-delete:hover {
                    background: #d32f2f;
                }
            `}</style>
        </div>
    );
};

export default Categories;
